#!/usr/bin/env python3
# Diagnostic only: digests of everything the final link consumes, to name the crate whose code
# differs between two builds. Usage: object-digests.py <target/<triple>/release directory>
# Prints "<relative path>[<archive member>] <size> <sha256>" for every member of each .rlib/.a in
# deps/ (rustc objects *.rcgu.o and lib.rmeta separately) and for every file generated by a build
# script in build/*/out/. Standard library only.
import hashlib
import os
import sys


def members(data):
    """Members of a GNU or BSD ar archive (the formats written by rustc and llvm-ar)."""
    if not data.startswith(b"!<arch>\n"):
        yield "<not an archive>", data
        return
    pos, longnames = 8, b""
    while pos + 60 <= len(data):
        header = data[pos:pos + 60]
        name = header[:16].decode(errors="replace").rstrip()
        size = int(header[48:58].decode().strip())
        body = data[pos + 60:pos + 60 + size]
        pos += 60 + size + (size & 1)
        if name.startswith("#1/"):  # BSD: name stored before the body
            n = int(name[3:])
            name, body = body[:n].rstrip(b"\0").decode(errors="replace"), body[n:]
        elif name == "//":  # GNU long name table
            longnames = body
            continue
        elif name in ("/", "/SYM64/", "__.SYMDEF", "__.SYMDEF SORTED"):  # symbol index
            name = "<symbol index>"
        elif name.startswith("/") and name[1:].isdigit():
            start = int(name[1:])
            end = longnames.index(b"/\n", start)
            name = longnames[start:end].decode(errors="replace")
        else:
            name = name.rstrip("/")
        yield name, body


def main(root):
    rows = []
    deps = os.path.join(root, "deps")
    for entry in sorted(os.listdir(deps)) if os.path.isdir(deps) else []:
        if entry.endswith((".rlib", ".a")):
            with open(os.path.join(deps, entry), "rb") as f:
                data = f.read()
            for name, body in members(data):
                rows.append((f"deps/{entry}[{name}]", len(body), hashlib.sha256(body).hexdigest()))
    build = os.path.join(root, "build")
    for dirpath, _, files in os.walk(build):
        if f"{os.sep}out" not in dirpath[len(build):]:
            continue
        for name in files:
            path = os.path.join(dirpath, name)
            with open(path, "rb") as f:
                body = f.read()
            rows.append((os.path.relpath(path, root), len(body), hashlib.sha256(body).hexdigest()))
    for path, size, digest in sorted(rows):
        print(f"{path} {size} {digest}")


main(sys.argv[1])
